SELECT task_id FROM yunxiao_binding
WHERE scope = #{binding.scope} AND child_id = #{binding.childId}
ORDER BY task_id LIMIT 1

SELECT a.draft FROM yunxiao_auto_task a JOIN yunxiao_timer_task t ON t.task_id = a.task_id
WHERE a.task_id = #{taskId}

    AND t.scope = #{scope}

SELECT EXISTS (
    SELECT 1 FROM yunxiao_write
    WHERE task_id = #{taskId} AND scope = #{binding.scope} AND remote_id = #{binding.childId}
      AND (operation LIKE 'project-task:%' OR operation LIKE 'child:%')
)
